#ifdef HAVE_CONFIG_H
#  include <config.h>
#endif

#include "operations.h"
#include "options.h"
#include <locale.h>
#include <stdlib.h>
#include <string.h>
#include "share/compat.h"

#ifndef FUZZ_TOOL_METAFLAC
int main(int argc, char *argv[])
#else
static int main_to_fuzz(int argc, char *argv[])
#endif
{
        CommandLineOptions options;
        int ret = 0;

#ifdef __EMX__
        _response(&argc, &argv);
        _wildcard(&argc, &argv);
#endif
#ifdef _WIN32
        if (get_utf8_argv(&argc, &argv) != 0) {
                fputs("ERROR: failed to convert command line parameters to UTF-8\n", stderr);
                return 1;
        }
#endif

#ifdef _WIN32
        {
                const char *var;
                var = getenv("LC_ALL");
                if (!var)
                        var = getenv("LC_NUMERIC");
                if (!var)
                        var = getenv("LANG");
                if (!var || strcmp(var, "C") != 0)
                        setlocale(LC_ALL, "");
        }
#else
        setlocale(LC_ALL, "");
#endif
        init_options(&options);

        if ((ret = parse_options(argc, argv, &options)) == 0)
                ret = !do_operations(&options);
        else
                ret = 1;

        free_options(&options);

        return ret;
}
